&Options = new() &OptionsDesc = new() &OptionIndexes = new() LoadWWPContext.Call(&WWPContext)
Do 'LoadGridState' Do Case Case &DDOName.ToUpper() = !'DDO_DISTPERIODO' Do 'LoaddistPeriodoOptions' Case &DDOName.ToUpper() = !'DDO_DISTLOCALORIGEM' Do 'LoaddistLocalOrigemOptions' Case &DDOName.ToUpper() = !'DDO_DISTLOCALDESTINO' Do 'LoaddistLocalDestinoOptions' Case &DDOName.ToUpper() = !'DDO_DISTRECEBEDOR' Do 'LoaddistRecebedorOptions' Case &DDOName.ToUpper() = !'DDO_DISTROTACODIGO' Do 'LoaddistRotaCodigoOptions' EndCase
