Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsdistribuicaoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsdistribuicaoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsdistribuicaoWWGridState")) Endif
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFDISTCODIGO" &TFdistCodigo.FromString(&GridStateFilterValue.Value) &TFdistCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTREMCODIGO" &TFdistRemCodigo.FromString(&GridStateFilterValue.Value) &TFdistRemCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTPERIODO" &TFdistPeriodo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTPERIODO_SEL" &TFdistPeriodo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTLOCALORIGEM" &TFdistLocalOrigem.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTLOCALORIGEM_SEL" &TFdistLocalOrigem_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTDATAENVIO" &TFdistDataEnvio.FromString(&GridStateFilterValue.Value) &TFdistDataEnvio_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTLOCALDESTINO" &TFdistLocalDestino.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTLOCALDESTINO_SEL" &TFdistLocalDestino_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTDATARECEPCAO" &TFdistDataRecepcao.FromString(&GridStateFilterValue.Value) &TFdistDataRecepcao_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTRECEBEDOR" &TFdistRecebedor.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTRECEBEDOR_SEL" &TFdistRecebedor_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTROTACODIGO" &TFdistRotaCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTROTACODIGO_SEL" &TFdistRotaCodigo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTRECEBER_SEL" &TFdistReceber_SelsJson = &GridStateFilterValue.Value &TFdistReceber_Sels.FromJson(&TFdistReceber_SelsJson) Case &GridStateFilterValue.Name = !"TFDISTSTATUS_SEL" &TFdistStatus_SelsJson = &GridStateFilterValue.Value &TFdistStatus_Sels.FromJson(&TFdistStatus_SelsJson) EndCase EndFor If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'DISTCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distCodigo1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'DISTREMCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distRemCodigo1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'DISTDATAENVIO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distDataEnvio1.FromString(&GridStateDynamicFilter.Value) &distDataEnvio_To1.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector1 = !'DISTDATARECEPCAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distDataRecepcao1.FromString(&GridStateDynamicFilter.Value) &distDataRecepcao_To1.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector1 = !'DISTROTACODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distRotaCodigo1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'DISTPERIODO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distPeriodo1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'DISTLOCALORIGEMNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distLocalOrigemNome1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'DISTLOCALDESTINONOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &distLocalDestinoNome1.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector1 = !'DISTRECEBER' &distReceber1.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'DISTCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distCodigo2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'DISTREMCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distRemCodigo2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'DISTDATAENVIO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distDataEnvio2.FromString(&GridStateDynamicFilter.Value) &distDataEnvio_To2.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector2 = !'DISTDATARECEPCAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distDataRecepcao2.FromString(&GridStateDynamicFilter.Value) &distDataRecepcao_To2.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector2 = !'DISTROTACODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distRotaCodigo2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'DISTPERIODO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distPeriodo2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'DISTLOCALORIGEMNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distLocalOrigemNome2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'DISTLOCALDESTINONOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &distLocalDestinoNome2.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector2 = !'DISTRECEBER' &distReceber2.FromString(&GridStateDynamicFilter.Value) EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'DISTCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distCodigo3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'DISTREMCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distRemCodigo3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'DISTDATAENVIO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distDataEnvio3.FromString(&GridStateDynamicFilter.Value) &distDataEnvio_To3.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector3 = !'DISTDATARECEPCAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distDataRecepcao3.FromString(&GridStateDynamicFilter.Value) &distDataRecepcao_To3.FromString(&GridStateDynamicFilter.ValueTo) Case &DynamicFiltersSelector3 = !'DISTROTACODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distRotaCodigo3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'DISTPERIODO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distPeriodo3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'DISTLOCALORIGEMNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distLocalOrigemNome3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'DISTLOCALDESTINONOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &distLocalDestinoNome3.FromString(&GridStateDynamicFilter.Value) Case &DynamicFiltersSelector3 = !'DISTRECEBER' &distReceber3.FromString(&GridStateDynamicFilter.Value) EndCase EndIf EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoaddistPeriodoOptions'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&TFdistPeriodo = &SearchTxt &TFdistPeriodo_Sel.SetEmpty() For Each trnsdistribuicao Order distPeriodo using trnsdistribuicaoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &distCodigo1, &distRemCodigo1, &distDataEnvio1, &distDataEnvio_To1 , &distDataRecepcao1, &distDataRecepcao_To1, &distRotaCodigo1, &distPeriodo1, &distLocalOrigemNome1, &distLocalDestinoNome1 , &distReceber1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &distCodigo2, &distRemCodigo2 , &distDataEnvio2, &distDataEnvio_To2, &distDataRecepcao2, &distDataRecepcao_To2, &distRotaCodigo2, &distPeriodo2 , &distLocalOrigemNome2, &distLocalDestinoNome2, &distReceber2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &distCodigo3, &distRemCodigo3, &distDataEnvio3, &distDataEnvio_To3, &distDataRecepcao3, &distDataRecepcao_To3 , &distRotaCodigo3, &distPeriodo3, &distLocalOrigemNome3, &distLocalDestinoNome3, &distReceber3, &TFdistCodigo , &TFdistCodigo_To, &TFdistRemCodigo, &TFdistRemCodigo_To, &TFdistPeriodo, &TFdistPeriodo_Sel, &TFdistLocalOrigem , &TFdistLocalOrigem_Sel, &TFdistDataEnvio, &TFdistDataEnvio_To, &TFdistLocalDestino, &TFdistLocalDestino_Sel, &TFdistDataRecepcao , &TFdistDataRecepcao_To, &TFdistRecebedor, &TFdistRecebedor_Sel, &TFdistRotaCodigo, &TFdistRotaCodigo_Sel, &TFdistReceber_Sels , &TFdistStatus_Sels) Where prefCodigo = &prefCodigo
&count = 0 For Each trnsdistribuicao Order distPeriodo &count += 1 EndFor If not distPeriodo.IsEmpty() &Option = distPeriodo
&Options.Add(&Option) &OptionIndexes.Add(trim(&count.ToFormattedString())) EndIf If &Options.Count = 50 Exit EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
